using System.Text.Json;using Microsoft.Extensions.Options;using TradingSystem.Dashboard.Contracts;using TradingSystem.JobOrchestration;using TradingSystem.Jobs.Worker.Execution;
namespace TradingSystem.Jobs.Worker.Workers;
public sealed class OptimizationJobWorker(IDashboardJobQueue queue, OptimizationExecutionService executor, IOptions<JobWorkerOptions> options, ILogger<OptimizationJobWorker> logger):BackgroundService
{
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){var o = options.Value;if(!o.Enabled)return;var worker = $"optimization:{Environment.MachineName}:{Guid.NewGuid():N}";using var timer = new PeriodicTimer(TimeSpan.FromSeconds(Math.Max(1, o.PollSeconds)));do{var jobs = await queue.ClaimAsync("Optimization", worker, 1, TimeSpan.FromMinutes(o.ProcessingTimeoutMinutes), stoppingToken);foreach(var job in jobs)await Process(job, o, stoppingToken);}while(await timer.WaitForNextTickAsync(stoppingToken));}
 private async Task Process(DashboardJob job, JobWorkerOptions o, CancellationToken ct){try{await queue.ReportProgressAsync(job.JobId, 5, "Preparing parameter combinations", ct);var request = JsonSerializer.Deserialize<OptimizationRequest>(job.RequestJson, new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid optimization request.");var run = await executor.ExecuteAsync(request, o.Interval, ct);await queue.CompleteAsync(job.JobId, run, ct);}catch(Exception ex){logger.LogError(ex, "Optimization job {JobId} failed", job.JobId);await queue.FailAsync(job.JobId, ex.Message, o.MaximumAttempts, TimeSpan.FromSeconds(Math.Pow(2, job.AttemptCount)), ct);}}
}
